class CustomerDao
  def initialize(db)                       # injected Sequel::Database (or AR connection)
    @db = db
  end
  def find(id)
    row = @db[:customer].where(id: id).first    # dataset built, then executed
    row && Customer.new(row[:id], row[:name], row[:version])
  end
  def add(customer)
    @db.transaction { @db[:customer].insert(id: customer.id, name: customer.name) }
  end
end
